application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root { --ink: #18212f; --muted: #788397; --accent: #635bff; --accent-dark: #5149e7; --line: #e8ebf2; --surface: #ffffff; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; color: var(--ink); font-family: 'DM Sans', sans-serif; background: #f4f6fb; background-image: radial-gradient(circle at 12% 10%, #e7e6ff 0, transparent 27%), radial-gradient(circle at 90% 92%, #dff8f3 0, transparent 29%); }
.app-shell { width: min(100% - 32px, 650px); margin: 0 auto; padding: 68px 0 30px; }
.todo-card { background: rgba(255,255,255,.94); border: 1px solid rgba(255,255,255,.8); border-radius: 24px; padding: 34px; box-shadow: 0 22px 60px rgba(39, 51, 89, .11); }
.app-header { display: flex; align-items: center; gap: 16px; margin-bottom: 30px; }
.brand-mark { display: grid; place-items: center; width: 52px; height: 52px; border-radius: 16px; color: white; font-size: 27px; font-weight: 700; background: linear-gradient(135deg, #817aff, #5149e7); box-shadow: 0 9px 20px rgba(99,91,255,.27); }
.eyebrow { margin: 0 0 2px; color: var(--accent); font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
h1, h2 { font-family: 'Space Grotesk', sans-serif; }
h1 { margin: 0; font-size: clamp(28px, 6vw, 36px); letter-spacing: -.04em; }
.subtitle { margin: 3px 0 0; color: var(--muted); font-size: 14px; }
.add-form { display: flex; gap: 10px; margin-bottom: 34px; }
.add-form input { min-width: 0; flex: 1; border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px; outline: none; color: var(--ink); font: inherit; background: #fbfcfe; transition: .2s; }
.add-form input:focus { border-color: var(--accent); box-shadow: 0 0 0 4px rgba(99,91,255,.11); }
.add-form button { border: 0; border-radius: 12px; padding: 0 20px; color: white; background: var(--accent); font: 700 14px 'DM Sans', sans-serif; cursor: pointer; transition: .2s; }
.add-form button:hover { background: var(--accent-dark); transform: translateY(-1px); }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 13px; }
h2 { margin: 0; font-size: 18px; letter-spacing: -.02em; }
.count-pill { border-radius: 20px; padding: 6px 11px; color: var(--accent-dark); background: #eeedff; font-size: 12px; font-weight: 700; }
.task-list { display: grid; gap: 10px; }
.task { display: flex; align-items: center; gap: 13px; min-height: 62px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 14px; background: var(--surface); animation: rise .25s ease-out; }
@keyframes rise { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
.complete-button { flex: 0 0 auto; width: 25px; height: 25px; border: 2px solid #cdd2df; border-radius: 50%; color: white; background: transparent; cursor: pointer; }
.task[data-completed="true"] .complete-button { border-color: var(--accent); background: var(--accent); }
.task[data-completed="true"] .complete-button::after { content: '✓'; display: block; font-size: 15px; line-height: 20px; }
.task-text { flex: 1; overflow-wrap: anywhere; font-size: 15px; }
.task[data-completed="true"] .task-text { color: #9aa3b3; text-decoration: line-through; }
.delete-button { border: 0; padding: 8px; color: #a5adbb; background: transparent; font-size: 20px; line-height: 1; cursor: pointer; }
.delete-button:hover { color: #ef6375; }
.empty-state { padding: 31px 10px 20px; color: var(--muted); text-align: center; }
.empty-icon { margin-bottom: 9px; color: #aaa6ff; font-size: 25px; }
.empty-state p { margin: 0 0 4px; color: var(--ink); font-weight: 600; }
.empty-state span { font-size: 13px; }
.memory-note { margin: 18px 0 0; color: #8d97a9; font-size: 12px; text-align: center; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 480px) { .app-shell { padding-top: 28px; } .todo-card { padding: 24px 18px; border-radius: 20px; } .add-form button { padding: 0 14px; } }

application.javascript:
const form = document.getElementById('task-form');
const input = document.querySelector('[data-testid="task-input"]');
const list = document.querySelector('[data-testid="task-list"]');
const emptyState = document.getElementById('empty-state');
const countElement = document.querySelector('[data-testid="incomplete-count"]');
const countLabel = document.getElementById('count-label');

let tasks = [];

function updateSummary() {
  const remaining = tasks.filter(task => !task.completed).length;
  countElement.textContent = remaining;
  countLabel.textContent = remaining === 1 ? 'remaining' : 'remaining';
  emptyState.hidden = tasks.length > 0;
}

function render() {
  list.replaceChildren();
  tasks.forEach(task => {
    const item = document.createElement('div');
    item.className = 'task';
    item.dataset.testid = 'task';
    item.dataset.completed = String(task.completed);

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'complete-button';
    toggle.dataset.testid = 'task-complete';
    toggle.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
    toggle.setAttribute('aria-pressed', String(task.completed));
    toggle.addEventListener('click', () => {
      task.completed = !task.completed;
      render();
    });

    const text = document.createElement('span');
    text.className = 'task-text';
    text.dataset.testid = 'task-text';
    text.textContent = task.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.dataset.testid = 'task-delete';
    remove.setAttribute('aria-label', `Delete task: ${task.text}`);
    remove.textContent = '×';
    remove.addEventListener('click', () => {
      tasks = tasks.filter(candidate => candidate.id !== task.id);
      render();
    });

    item.append(toggle, text, remove);
    list.appendChild(item);
  });
  updateSummary();
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  tasks.push({ id: Date.now() + Math.random(), text, completed: false });
  input.value = '';
  render();
  input.focus();
});

render();
